	/**
	 * Widgets that need {@link #isVisibleIncludingAncestors(int)} instead of the
	 * plain
	 * {@link #isVisible(int)} check used for {@link #MODAL_CONTENT_WIDGETS}.
	 *
	 * PohCostumes.ITEMS: opening the costume room's search box and then pressing
	 * Escape takes
	 * a different closing path than a normal close - instead of unloading the
	 * group (like a
	 * normal close) or flipping the widget's own hidden flag, it only hides an
	 * ancestor
	 * container above PohCostumes' own root. Every widget in the group keeps
	 * reporting
	 * selfHidden=false forever, so {@link #isVisible(int)} never notices it
	 * closed.
	 */
	private static final int[] MODAL_CONTENT_WIDGETS_ANCESTOR_AWARE = {
			InterfaceID.PohCostumes.ITEMS,
			InterfaceID.BankDepositImp.INVENTORY,
			InterfaceID.OmnishopMain.INFINITY,
	};

	/**
	 * True everywhere except while the bank, a shop, the trade screen, or a similar
	 * modal
	 */
	boolean shouldRemapEscape() {
		boolean modalInterfaceOpen = false;
		for (int widgetId : MODAL_CONTENT_WIDGETS) {
			if (isVisible(widgetId)) {
				modalInterfaceOpen = true;
				log.debug("shouldRemapEscape: blocked by widget {}", widgetId);
				break;
			}
		}

		if (!modalInterfaceOpen && ancestorAwareWidgetOpen) {
			modalInterfaceOpen = true;
			log.debug("shouldRemapEscape: blocked by cached ancestor-aware widget state");
		}

		int debugWidgetId = config.debugWidgetId();
		if (debugWidgetId != 0) {
			boolean debugWidgetVisible = isVisible(debugWidgetId);
			log.debug("shouldRemapEscape: debugWidgetId={} visible={}", debugWidgetId, debugWidgetVisible);
			modalInterfaceOpen |= debugWidgetVisible;
		}

		if (collectionLogEscapePassthroughArmAtTick != -1
				&& client.getTickCount() >= collectionLogEscapePassthroughArmAtTick) {
			log.debug("shouldRemapEscape: consuming armed collection log escape passthrough");
			modalInterfaceOpen = true;
			collectionLogEscapePassthroughArmAtTick = -1;
		}

		if (modalInterfaceOpen) {
			forceClearStuckBankSearch();
		}

		log.debug("shouldRemapEscape: modalInterfaceOpen={}", modalInterfaceOpen);

		return !modalInterfaceOpen;
	}

	/**
	 * Works around a client bug: closing the bank while its search box is still
	 * active leaves
	 * the chatbox message layer stuck in {@link InputType#SEARCH}, which in turn
	 * leaves the
	 * whole Bankmain interface group permanently reporting itself as visible -
	 * confirmed by
	 * testing both Bankmain.ITEMS and Bankmain.FRAME, which get stuck identically,
	 * so this
	 * isn't fixable by picking a different child widget. Forcibly clears that
	 * leftover chatbox
	 * state with the same script the core Bank plugin's own search reset uses
	 * (BankSearch#reset), letting the interface's hidden state catch up on a later
	 * tick.
	 * Harmless if the bank is genuinely open and being searched right now - it just
	 * mirrors
	 * what native Escape already does in that case (cancel the search, not close
	 * the bank).
	 */
	private void forceClearStuckBankSearch() {
		if (client.getVarcIntValue(VarClientID.MESLAYERMODE) != InputType.SEARCH.getType()) {
			return;
		}

		log.debug("shouldRemapEscape: forcing stuck bank search closed");
		clientThread.invoke(() -> client.runScript(ScriptID.MESSAGE_LAYER_CLOSE, 1, 1, 0));
	}

	private boolean isVisible(int component) {
		Widget w = client.getWidget(component);
		return w != null && !w.isSelfHidden();
	}

	/**
	 * Like {@link #isVisible(int)}, but uses {@link Widget#isHidden()} - which
	 * also accounts for
	 * ancestors, unlike {@link Widget#isSelfHidden()} - since PohCostumes' stuck-
	 * after-search
	 * state hides it via an ancestor in the client's interface-layer system
	 * rather than any
	 * widget's own flag. isHidden() asserts it's called on the client thread, so
	 * this may only
	 * be called from {@link #onGameTick(GameTick)} or other client-thread
	 * callbacks - never
	 * directly from {@link #shouldRemapEscape()}, which runs on the AWT thread
	 * and reads the
	 * cached {@link #ancestorAwareWidgetOpen} instead.
	 */
	private boolean isVisibleIncludingAncestors(int component) {
		Widget w = client.getWidget(component);
		return w != null && !w.isHidden();
	}
}

package com.ella.chatboxescapeblocker;

import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ModifierlessKeybind;

@ConfigGroup(ChatboxEscapeBlockerConfig.GROUP)
public interface ChatboxEscapeBlockerConfig extends Config
{
	String GROUP = "chatboxescapeblocker";

	@ConfigItem(
		keyName = "remapTo",
		name = "Remap Escape to",
		description = "Whenever Escape is pressed, send this key to the game instead - except while the bank, "
			+ "Grand Exchange, or a similar interface is open, where Escape keeps closing it normally. Whatever "
			+ "this key normally does happens instead of Escape's usual action (e.g. set it to your Inventory "
			+ "tab hotkey). Leave not set to just block Escape."
	)
	default ModifierlessKeybind remapTo()
	{
		return new ModifierlessKeybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
		keyName = "debugWidgetId",
		name = "Debug widget ID",
		description = "For testing: also treat this widget ID (from the RuneLite Developer Tools widget "
			+ "inspector, e.g. 5570562) as a modal interface that should keep Escape's normal behavior. Its "
			+ "visibility is logged at debug level every time Escape is pressed, so you can confirm a candidate "
			+ "widget actually flips hidden/visible correctly before adding it to the plugin's source. Leave 0 "
			+ "to disable."
	)
	default int debugWidgetId()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "printOpenInterfaces",
		name = "Print open interfaces",
		description = "Check this to print the widget IDs of every currently-open interface (from the plugin's "
			+ "modal widget list, plus the debug widget ID above if set) to the game chat. It's a one-shot "
			+ "action, not a persistent setting - it unchecks itself right after printing."
	)
	default boolean printOpenInterfaces()
	{
		return false;
	}
}
